  (24, 'aperitif-restaurant', 'why_its_here', (select count(*)::int from venues where slug = 'aperitif-restaurant' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'acb35db5e1c07f0c32d1ca2cbbd225e7'), md5(U&'Ap\00E9ritif is a degustation restaurant in Petulu, near Ubud, where the cooking mixes French, Japanese and Indonesian influences.') = '8c502c7e9c84db4fe5a3d343162e8142'),
