  (29, 'ayam-betutu-khas-gilimanuk', 'why_its_here', (select count(*)::int from venues where slug = 'ayam-betutu-khas-gilimanuk' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '1d921cde9f572bd907188520a2b57157'), md5('A Denpasar kitchen that specialises in ayam betutu: Gilimanuk-style chicken slow-cooked in Balinese spice paste until it falls off the bone. It is a focused, no-frills local place where the betutu and the sambals are the reason to come.') = 'b7aa3a80df85f6f6c2f7317dbc7adb2d'),
  (30, 'ayam-betutu-khas-gilimanuk', 'best_for', (select count(*)::int from venues where slug = 'ayam-betutu-khas-gilimanuk' and status = 'active' and publication_status = 'published' and md5(best_for) = 'd020ad110f449a2b40e7b2234ce35931'), md5('A spice-forward Balinese lunch where residents eat, away from the tourist strip') = '27d6daac8f757700a791943b65da6d2d'),
